import type {
  CalaEntity,
  CandidateQualification,
  CriterionEvidence,
  Geography,
  RankedCompany,
  ScoreBreakdown,
  Sector,
  ThesisPlan,
} from "./types";
import { geographyEvidenceTerms, sectorEvidenceTerms } from "./taxonomy.ts";

const fieldAliases = {
  name: ["company", "name", "company_name", "startup"],
  location: ["location", "headquarters", "hq", "city", "country"],
  sector: ["sector", "industry", "category"],
  founded: ["founded_year", "founded", "year_founded", "founded_date"],
  funding: ["total_funding", "funding", "funding_amount", "total_raised", "amount_raised"],
  round: ["latest_round", "round_type", "funding_round", "last_round"],
  date: ["latest_event_date", "latest_funding_date", "date", "year"],
  momentum: ["momentum_signal", "recent_signal", "signal", "recent_development", "latest_event"],
  source: ["source_url", "source", "url", "evidence_url"],
} as const;

function normalizedEntries(row: Record<string, unknown>): Map<string, unknown> {
  return new Map(Object.entries(row).map(([key, value]) => [key.toLowerCase().replace(/[\s-]+/g, "_"), value]));
}

function pick(entries: Map<string, unknown>, aliases: readonly string[]): unknown {
  for (const alias of aliases) {
    if (entries.has(alias)) return entries.get(alias);
  }
  return null;
}

function asText(value: unknown): string | null {
  if (typeof value === "string") {
    const trimmed = value.trim();
    return trimmed && trimmed.toLowerCase() !== "null" ? trimmed.slice(0, 500) : null;
  }
  if (typeof value === "number" && Number.isFinite(value)) return String(value);
  return null;
}

function asYear(value: unknown): number | null {
  const text = asText(value);
  if (!text) return null;
  const match = text.match(/\b(19|20)\d{2}\b/);
  const year = match ? Number(match[0]) : Number(text);
  return Number.isInteger(year) && year >= 1900 && year <= 2026 ? year : null;
}

function asFundingMillions(value: unknown): number | null {
  if (typeof value === "number" && Number.isFinite(value)) {
    if (value < 0) return null;
    return value >= 10_000 ? Math.round((value / 1_000_000) * 10) / 10 : Math.round(value * 10) / 10;
  }
  const text = asText(value);
  if (!text) return null;
  const cleaned = text.replace(/,/g, "");
  const match = cleaned.match(/(-?\d+(?:\.\d+)?)\s*(b|bn|billion|m|million|k|thousand)?/i);
  if (!match) return null;
  const amount = Number(match[1]);
  const unit = (match[2] || "").toLowerCase();
  if (!Number.isFinite(amount) || amount < 0) return null;
  if (["b", "bn", "billion"].includes(unit)) return Math.round(amount * 10_000) / 10;
  if (["k", "thousand"].includes(unit)) return Math.round((amount / 1_000) * 10) / 10;
  if (["m", "million"].includes(unit)) return Math.round(amount * 10) / 10;
  return amount >= 10_000 ? Math.round((amount / 1_000_000) * 10) / 10 : Math.round(amount * 10) / 10;
}

function asDate(value: unknown): string | null {
  const text = asText(value);
  if (!text) return null;
  const parsed = Date.parse(text);
  if (!Number.isNaN(parsed)) return new Date(parsed).toISOString().slice(0, 10);
  const year = asYear(value);
  return year ? `${year}-01-01` : null;
}

function asSafeUrl(value: unknown): string | null {
  const text = asText(value);
  if (!text || text.length > 2_048) return null;
  try {
    const url = new URL(text);
    return url.protocol === "https:" ? url.toString() : null;
  } catch {
    return null;
  }
}

function normalizedPhrase(value: string): string {
  return ` ${value.normalize("NFKD").replace(/[\u0300-\u036f]/g, "").toLowerCase().replace(/[^a-z0-9]+/g, " ").trim()} `;
}

function includesTerm(value: string, term: string): boolean {
  return normalizedPhrase(value).includes(normalizedPhrase(term));
}

function matchesSector(value: string | null, sector: Sector): boolean {
  return Boolean(value && sectorEvidenceTerms(sector).some((term) => includesTerm(value, term)));
}

function matchesGeography(value: string | null, geography: Geography): boolean {
  return Boolean(value && geographyEvidenceTerms(geography).some((term) => includesTerm(value, term)));
}

function freshnessPoints(date: string | null): number {
  if (!date) return 0;
  const days = (Date.now() - Date.parse(date)) / 86_400_000;
  if (!Number.isFinite(days) || days < -1) return 0;
  if (days <= 365) return 20;
  if (days <= 730) return 12;
  if (days <= 1_460) return 5;
  return 0;
}

function qualificationFor(
  plan: ThesisPlan,
  location: string | null,
  sector: string | null,
  foundedYear: number | null,
  funding: number | null,
): { qualification: CandidateQualification; missingCriteria: string[]; failedCriteria: string[]; geographyMatch: boolean; sectorMatch: boolean; criterionEvidence: CriterionEvidence[] } {
  const missingCriteria: string[] = [];
  const failedCriteria: string[] = [];
  const geographyMatch = matchesGeography(location, plan.geography);
  const sectorMatch = matchesSector(sector, plan.sector);

  if (foundedYear === null) missingCriteria.push("Founding year is not confirmed");
  else if (foundedYear < plan.founded_after) failedCriteria.push(`Founded in ${foundedYear}, before the ${plan.founded_after} threshold`);

  if (funding === null) missingCriteria.push("Disclosed funding is not confirmed");
  else if (funding > plan.max_funding_millions) failedCriteria.push(`€${funding}M disclosed funding exceeds the €${plan.max_funding_millions}M ceiling`);

  if (!location) missingCriteria.push("Location is not confirmed");
  else if (!geographyMatch) failedCriteria.push(`Geography fit for ${plan.geography} is not demonstrated`);

  if (!sector) missingCriteria.push("Sector is not confirmed");
  else if (!sectorMatch) failedCriteria.push(`Sector fit for ${plan.sector} is not demonstrated`);

  const criterionEvidence: CriterionEvidence[] = [
    {
      criterion: "founding_year",
      label: "Founding year",
      expected_value: foundedYear,
      outcome: foundedYear === null ? "unknown" : foundedYear >= plan.founded_after ? "matches" : "fails",
      status: "unsupported",
      claim: null,
      source_url: null,
      source_label: null,
    },
    {
      criterion: "funding",
      label: "Funding",
      expected_value: funding,
      outcome: funding === null ? "unknown" : funding <= plan.max_funding_millions ? "matches" : "fails",
      status: "unsupported",
      claim: null,
      source_url: null,
      source_label: null,
    },
    {
      criterion: "geography",
      label: "Geography",
      expected_value: plan.geography,
      outcome: location === null ? "unknown" : geographyMatch ? "matches" : "fails",
      status: "unsupported",
      claim: null,
      source_url: null,
      source_label: null,
    },
    {
      criterion: "sector",
      label: "Sector",
      expected_value: plan.sector,
      outcome: sector === null ? "unknown" : sectorMatch ? "matches" : "fails",
      status: "unsupported",
      claim: null,
      source_url: null,
      source_label: null,
    },
  ];

  return {
    // Structured rows identify candidate facts, but Cala context with a safe
    // origin must corroborate each hard criterion before qualification.
    qualification: "needs_verification",
    missingCriteria,
    failedCriteria,
    geographyMatch,
    sectorMatch,
    criterionEvidence,
  };
}

export function rankCompanies(
  rows: Record<string, unknown>[],
  _entities: CalaEntity[],
  plan: ThesisPlan,
): RankedCompany[] {
  const seen = new Set<string>();
  const companies: Omit<RankedCompany, "rank">[] = [];

  for (const row of rows.slice(0, 20)) {
    const entries = normalizedEntries(row);
    const name = asText(pick(entries, fieldAliases.name));
    if (!name || seen.has(name.toLowerCase())) continue;
    seen.add(name.toLowerCase());

    const location = asText(pick(entries, fieldAliases.location));
    const sector = asText(pick(entries, fieldAliases.sector));
    const foundedYear = asYear(pick(entries, fieldAliases.founded));
    const funding = asFundingMillions(pick(entries, fieldAliases.funding));
    const latestRound = asText(pick(entries, fieldAliases.round));
    const latestDate = asDate(pick(entries, fieldAliases.date));
    const momentum = asText(pick(entries, fieldAliases.momentum));
    const sourceUrl = asSafeUrl(pick(entries, fieldAliases.source));
    const qualification = qualificationFor(plan, location, sector, foundedYear, funding);
    const sourceBacked = Boolean(sourceUrl);

    const scoreBreakdown: ScoreBreakdown = {
      thesis_evidence: (qualification.geographyMatch ? 15 : 0) + (qualification.sectorMatch ? 15 : 0),
      capital_evidence: funding === null || !sourceBacked ? 0 : 20,
      evidence_freshness: freshnessPoints(latestDate),
      signal_evidence: momentum && sourceBacked ? 15 : 0,
      completeness: Math.round(([
        location,
        sector,
        foundedYear,
        funding,
        latestDate,
        momentum,
        sourceUrl,
      ].filter((value) => value !== null && value !== undefined).length / 7) * 15),
    };
    const score = Object.values(scoreBreakdown).reduce((sum, value) => sum + value, 0);
    const missingFields = [
      ["location", location],
      ["sector", sector],
      ["founding year", foundedYear],
      ["funding", funding],
      ["latest event date", latestDate],
      ["latest signal", momentum],
      ["source", sourceUrl],
    ].filter(([, value]) => value === null || value === undefined).map(([label]) => String(label));

    companies.push({
      name,
      location,
      sector,
      founded_year: foundedYear,
      funding_millions: funding,
      latest_round: latestRound,
      latest_event_date: latestDate,
      momentum_signal: momentum,
      source_url: sourceUrl,
      score,
      score_breakdown: scoreBreakdown,
      missing_fields: missingFields,
      qualification: qualification.qualification,
      missing_criteria: qualification.missingCriteria,
      failed_criteria: qualification.failedCriteria,
      criterion_evidence: qualification.criterionEvidence,
      evidence_claims: [],
      conflicting_facts: [],
    });
  }

  const qualificationOrder: Record<CandidateQualification, number> = {
    verified_match: 0,
    needs_verification: 1,
    outside_thesis: 2,
  };

  return companies
    .sort((a, b) => qualificationOrder[a.qualification] - qualificationOrder[b.qualification] || b.score - a.score || a.name.localeCompare(b.name))
    .slice(0, plan.result_count)
    .map((company, index) => ({ ...company, rank: index + 1 }));
}
lib/evidence.ts
import type {
  CalaContext,
  CalaEntity,
  CalaExplanation,
  CriterionEvidence,
  EvidenceClaim,
  Geography,
  RankedCompany,
  Sector,
} from "./types";
import { geographyEvidenceTerms, sectorEvidenceTerms } from "./taxonomy.ts";

const CONFLICT_PATTERN = /\b(conflict(?:ing|s|ed)?|contradict(?:ory|s|ed|ion)?|inconsistent|sources? disagree|figures? (?:differ|vary))\b/i;
const FUNDING_PATTERN = /\b(fund(?:ing|ed)?|rais(?:e|ed|ing)|financ(?:e|ed|ing)|capital|investment|total raised)\b/i;
const GEOGRAPHY_PATTERN = /\b(headquarter(?:s|ed)?|based|located|location|office|city|country|from)\b/i;
const SECTOR_PATTERN = /\b(sector|industry|company|startup|platform|software|technology|tech)\b/i;

function normalizedText(value: string): string {
  return ` ${value.normalize("NFKD").replace(/[\u0300-\u036f]/g, "").toLowerCase().replace(/[^a-z0-9]+/g, " ").trim()} `;
}

function matchingEntity(companyName: string, entities: CalaEntity[]): CalaEntity | undefined {
  const company = normalizedText(companyName);
  return entities.find((entity) => [entity.name, ...(entity.mentions || [])]
    .some((name) => {
      const candidate = normalizedText(name);
      return candidate === company || candidate.includes(company) || company.includes(candidate);
    }));
}

function companyTerms(companyName: string, entities: CalaEntity[]): string[] {
  const entity = matchingEntity(companyName, entities);
  return [...new Set([companyName, ...(entity?.mentions || [])])]
    .map(normalizedText)
    .filter((term) => term.trim().length >= 3);
}

function isRelevant(text: string, terms: string[]): boolean {
  const normalized = normalizedText(text);
  return terms.some((term) => normalized.includes(term));
}

function safeOrigin(context: CalaContext): { url: string; label: string | null } | null {
  for (const origin of context.origins) {
    try {
      const url = new URL(origin.url);
      if (url.protocol === "https:") return { url: url.toString(), label: origin.label };
    } catch {
      // Ignore malformed provider origins.
    }
  }
  return null;
}

function claimFrom(content: string, contexts: CalaContext[]): EvidenceClaim {
  const origin = contexts.map(safeOrigin).find(Boolean) ?? null;
  return {
    claim: content.replace(/\s+/g, " ").trim().slice(0, 360),
    source_url: origin?.url ?? null,
    source_label: origin?.label ?? null,
  };
}

function uniqueClaims(claims: EvidenceClaim[]): EvidenceClaim[] {
  const seen = new Set<string>();
  return claims.filter((claim) => {
    const key = `${claim.claim.toLowerCase()}|${claim.source_url ?? ""}`;
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });
}

function containsAnyTerm(text: string, expectedTerms: readonly string[]): boolean {
  const normalized = normalizedText(text);
  return expectedTerms.some((term) => normalized.includes(normalizedText(term)));
}

function withoutCompanyAliases(text: string, terms: readonly string[]): string {
  let normalized = normalizedText(text);
  for (const term of [...terms].sort((left, right) => right.length - left.length)) {
    normalized = normalized.replaceAll(term, " ");
  }
  return normalized.replace(/\s+/g, " ");
}

function normalizedNumericAmount(value: string, hasUnit: boolean): number | null {
  if (/^\d{1,3}(?:([.,])\d{3})(?:\1\d{3})+$/.test(value)) {
    return Number(value.replace(/[.,]/g, ""));
  }
  if (!hasUnit && /^\d{1,3}[.,]\d{3}$/.test(value)) {
    return Number(value.replace(/[.,]/g, ""));
  }
  if (value.includes(",") && value.includes(".")) {
    const decimalSeparator = value.lastIndexOf(",") > value.lastIndexOf(".") ? "," : ".";
    const thousandsSeparator = decimalSeparator === "," ? "." : ",";
    return Number(value.replaceAll(thousandsSeparator, "").replace(decimalSeparator, "."));
  }
  const amount = Number(value.replace(",", "."));
  return Number.isFinite(amount) ? amount : null;
}

function fundingAmountsMillions(text: string): number[] {
  const amounts: number[] = [];
  const pattern = /(?:€|eur\s*)?(\d+(?:(?:[.,])\d+)*)\s*(b|bn|billion|m|million|k|thousand)?\b/gi;
  for (const match of text.matchAll(pattern)) {
    const rawAmount = match[1];
    const unit = (match[2] || "").toLowerCase();
    const amount = normalizedNumericAmount(rawAmount, Boolean(unit));
    if (amount === null) continue;
    if (["b", "bn", "billion"].includes(unit)) amounts.push(amount * 1_000);
    else if (["k", "thousand"].includes(unit)) amounts.push(amount / 1_000);
    else if (["m", "million"].includes(unit)) amounts.push(amount);
    else if (/€|eur/i.test(match[0])) amounts.push(amount >= 10_000 ? amount / 1_000_000 : amount);
  }
  return amounts;
}

function supportsCriterion(
  criterion: CriterionEvidence,
  company: RankedCompany,
  text: string,
  companyAliases: readonly string[],
): boolean {
  switch (criterion.criterion) {
    case "founding_year":
      return company.founded_year !== null
        && new RegExp(`\\b(founded|established|incorporated|launched)\\D{0,24}${company.founded_year}\\b|\\b${company.founded_year}\\D{0,24}(founded|established|incorporated)\\b`, "i").test(text);
    case "funding":
      return company.funding_millions !== null
        && FUNDING_PATTERN.test(text)
        && fundingAmountsMillions(text).some((amount) => Math.abs(amount - company.funding_millions!) < 0.001);
    case "geography":
      return typeof criterion.expected_value === "string"
        && GEOGRAPHY_PATTERN.test(text)
        && containsAnyTerm(text, geographyEvidenceTerms(criterion.expected_value as Geography));
    case "sector": {
      // A company name such as "Acme AI" is an identifier, not a sourced
      // assertion that the company operates in artificial intelligence.
      const directAssertion = withoutCompanyAliases(text, companyAliases);
      return typeof criterion.expected_value === "string"
        && SECTOR_PATTERN.test(directAssertion)
        && containsAnyTerm(directAssertion, sectorEvidenceTerms(criterion.expected_value as Sector));
    }
  }
}

function unsupportedReason(criterion: CriterionEvidence): string {
  return `Cala source evidence for ${criterion.label.toLowerCase()} is not confirmed`;
}

export function linkEvidenceToCompanies(
  companies: RankedCompany[],
  contexts: CalaContext[],
  explanations: CalaExplanation[],
  entities: CalaEntity[] = [],
): RankedCompany[] {
  return companies.map((company) => {
    const terms = companyTerms(company.name, entities);
    const relevantLinks = contexts
      .filter((context) => isRelevant(context.content, terms))
      .map((context) => ({
        context,
        origin: safeOrigin(context),
        explained: explanations.some((explanation) => explanation.references.includes(context.id) && isRelevant(explanation.content, terms)),
      }))
      .filter((link): link is { context: CalaContext; origin: { url: string; label: string | null }; explained: boolean } => Boolean(link.origin))
      .sort((left, right) => Number(right.explained) - Number(left.explained));

    const criterionEvidence = company.criterion_evidence.map((criterion): CriterionEvidence => {
      const conflict = relevantLinks.find((link) => {
        const text = link.context.content;
        return CONFLICT_PATTERN.test(text) && supportsCriterion(criterion, company, text, terms);
      });
      if (conflict) {
        return {
          ...criterion,
          status: "conflicting",
          claim: conflict.context.content.replace(/\s+/g, " ").trim().slice(0, 240),
          source_url: conflict.origin.url,
          source_label: conflict.origin.label,
        };
      }

      const support = relevantLinks.find((link) => {
        const text = link.context.content;
        return !CONFLICT_PATTERN.test(text) && supportsCriterion(criterion, company, text, terms);
      });
      if (!support) return criterion;
      return {
        ...criterion,
        status: "supported",
        claim: support.context.content.replace(/\s+/g, " ").trim().slice(0, 240),
        source_url: support.origin.url,
        source_label: support.origin.label,
      };
    });

    const qualifyingSourceUrls = new Set(criterionEvidence
      .filter((criterion) => criterion.status !== "unsupported" && criterion.source_url)
      .map((criterion) => criterion.source_url));
    // Explanations help prioritize Cala contexts, but only direct context that
    // supports a hard criterion (or reports a conflict) becomes a receipt.
    const claims = uniqueClaims(relevantLinks
      .filter((link) => qualifyingSourceUrls.has(link.origin.url) || CONFLICT_PATTERN.test(link.context.content))
      .map((link) => claimFrom(link.context.content, [link.context])))
      .slice(0, 3);
    const conflictingFacts = claims.filter((claim) => CONFLICT_PATTERN.test(claim.claim));
    const evidenceClaims = claims.filter((claim) => !CONFLICT_PATTERN.test(claim.claim));

    const hasConflict = conflictingFacts.length > 0 || criterionEvidence.some((criterion) => criterion.status === "conflicting");
    const allSupportedMatches = criterionEvidence.every((criterion) => criterion.outcome === "matches" && criterion.status === "supported");
    const hasSupportedFailure = criterionEvidence.some((criterion) => criterion.outcome === "fails" && criterion.status === "supported");
    const qualification = hasConflict
      ? "needs_verification"
      : hasSupportedFailure
        ? "outside_thesis"
        : allSupportedMatches
          ? "verified_match"
          : "needs_verification";
    const missingCriteria = [...company.missing_criteria];
    for (const criterion of criterionEvidence) {
      if (criterion.status === "unsupported" && !missingCriteria.includes(unsupportedReason(criterion))) {
        missingCriteria.push(unsupportedReason(criterion));
      }
    }
    if (hasConflict) missingCriteria.push("Conflicting Cala evidence requires review");

    return {
      ...company,
      qualification,
      missing_criteria: [...new Set(missingCriteria)],
      criterion_evidence: criterionEvidence,
      evidence_claims: evidenceClaims,
      conflicting_facts: conflictingFacts,
    };
  });
}
